export type MarketingCode = keyof typeof CODES;
export const MARKETING_KNOWN_CODES = Object.keys(CODES) as MarketingCode[];

/** Families that carry a variable part: an HTTP status, a remote state or a scheduler category. */
const PATTERNS: Array<{ test: RegExp; text: (match: RegExpExecArray) => Entry }> = [
  { test: /^research-apify-refused-(400|401|402|403|404|413|422)$/, text: (m) => ['investigate', `Apify refused the research start (HTTP ${m[1]}); no run was created.`, `Apify odmítlo spuštění výzkumu (HTTP ${m[1]}); žádný běh nevznikl.`] },
  { test: /^meta-http-(\d{3})$/, text: (m) => ['token', `Instagram rejected the request (HTTP ${m[1]}).`, `Instagram požadavek odmítl (HTTP ${m[1]}).`] },
  { test: /^media-(?:page-)?http-(\d{3})$/, text: (m) => ['media', `The source site refused the picture (HTTP ${m[1]}).`, `Zdrojový web obrázek odmítl (HTTP ${m[1]}).`] },
  { test: /^remote-container-([a-z_]+)$/, text: (m) => ['verify', `Instagram reports the post as ${m[1]!.replace(/_/g, ' ')}.`, `Instagram hlásí stav příspěvku ${m[1]!.replace(/_/g, ' ')}.`] },
  { test: /^container-(error|expired|failed)$/, text: () => ['investigate', 'Instagram could not process the images; nothing was published.', 'Instagram obrázky nezpracoval; nic se nepublikovalo.'] },
  { test: /^(collection|media|briefs|generation|publishing|reconciliation|token|renewal|purge|retention)-failed$/, text: (m) => ['auto', `The scheduler step “${m[1]}” failed.`, `Krok plánovače „${m[1]}“ selhal.`] },
  { test: /^provider-/, text: () => ['regenerate', 'The model provider did not finish generation.', 'Poskytovatel modelu generování nedokončil.'] },
  { test: /^render-preflight-/, text: () => ['regenerate', 'The pre-generation render check did not pass.', 'Kontrola vykreslení před generováním neprošla.'] },
  { test: /^pilot-/, text: () => ['investigate', 'The pilot run is not admitted.', 'Pilotní běh není povolený.'] },
  { test: /^offline-import-/, text: () => ['investigate', 'The offline import was refused.', 'Offline import byl odmítnut.'] },
  { test: /^challenge-/, text: () => ['regenerate', 'The coding challenge did not fit its template.', 'Programátorská úloha se nevešla do šablony.'] },
  { test: /^media-page-/, text: () => ['auto', 'The source page with the pictures could not be read.', 'Zdrojovou stránku s obrázky nelze načíst.'] },
  { test: /^source-/, text: () => ['source', 'The source could not be checked.', 'Zdroj nešlo ověřit.'] },
  { test: /^daily-source-/, text: () => ['source', 'The source date is not valid.', 'Datum zdroje není platné.'] },
  { test: /^media-/, text: () => ['media', 'A source picture could not be used.', 'Zdrojový obrázek nelze použít.'] },
  { test: /^brief-/, text: () => ['source', 'The brief could not continue.', 'Podklad nemohl pokračovat.'] },
  { test: /^collection-/, text: () => ['auto', 'The source collection reported a problem.', 'Sběr zdrojů nahlásil problém.'] },
];

/** Kebab-case (Meta's remote states keep their underscore): anything else is never shown, even in Details. */
const CODE_SHAPE = /^[a-z][a-z0-9_-]{0,99}$/;
const GENERIC: Entry = ['investigate', 'Something did not finish as expected.', 'Něco neproběhlo podle očekávání.'];

export type MarketingCodeDescription = { code: string | null; known: boolean; happened: string; next: string };

/** Collection and event codes already have owner text in the Sources tab's dictionary; reuse it instead of a second copy. */
function sourcesEntry(code: string): Entry | null {
  const en = dneskaiSources.en.blockers[code] ?? dneskaiSources.en.eventReasons[code];
  const cs = dneskaiSources.cs.blockers[code] ?? dneskaiSources.cs.eventReasons[code];
  return en && cs ? [code.startsWith('brief-') ? 'source' : 'auto', en, cs] : null;
}

function entryFor(code: string): Entry | null {
  if (Object.hasOwn(CODES, code)) return CODES[code as MarketingCode];
  const sources = sourcesEntry(code);
  if (sources) return sources;
  for (const pattern of PATTERNS) { const match = pattern.test.exec(code); if (match) return pattern.text(match); }
  return null;
}

/** Plain text for a recorded code. An unknown or malformed code reads as the generic text; Details shows a safe code. */
export function describeMarketingCode(value: string | null | undefined, lang: MarketingCodeLang): MarketingCodeDescription {
  const code = typeof value === 'string' && CODE_SHAPE.test(value) ? value : null;
  const entry = code ? entryFor(code) : null;
  const [next, en, cs] = entry ?? GENERIC;
  return { code, known: entry !== null, happened: lang === 'cs' ? cs : en, next: NEXT[next][lang] };
}

/** Whether a code has its own text (directly or through a family pattern). */
export function marketingCodeKnown(code: string): boolean {
  return CODE_SHAPE.test(code) && entryFor(code) !== null;
}

/** The English and Czech text of a listed code, for the coverage test. */
export function marketingCodeTexts(code: MarketingCode): { en: string; cs: string; next: Text } {
  const [next, en, cs] = CODES[code];
  return { en, cs, next: NEXT[next] };
}
